using CGSmartK.Application;using CGSmartK.Domain;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace CGSmartK.Web.Controllers;[Authorize(Policy="KnowledgeAdministrator")]public sealed class KnowledgeController(IKnowledgeService service,IDocumentRepository documents):Controller {public async Task<IActionResult> Index(CancellationToken ct)=>View(await documents.ListAsync(ct));public IActionResult Upload()=>View();[HttpPost][RequestSizeLimit(21*1024*1024)]public async Task<IActionResult> Upload(IFormFile file,string title,string category,Classification classification,string? allowedGroups,CancellationToken ct){try{await using var stream=file.OpenReadStream();var groups=(allowedGroups??"").Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries).ToHashSet();var id=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value??"unknown";var doc=await service.UploadAsync(new(file.FileName,file.ContentType,file.Length,stream,title,category,classification,groups,id),ct);return RedirectToAction(nameof(Details),new{id=doc.Id});}catch(ArgumentException ex){ModelState.AddModelError("file",ex.Message);return View();}}public async Task<IActionResult> Details(Guid id,CancellationToken ct){var d=await documents.GetAsync(id,ct);return d is null?NotFound():View(d);}[HttpPost]public async Task<IActionResult> Reindex(Guid id,CancellationToken ct){await service.ReindexAsync(id,ct);return RedirectToAction(nameof(Details),new{id});}[HttpPost]public async Task<IActionResult> Delete(Guid id,bool confirm,CancellationToken ct){await service.DeleteAsync(id,confirm,ct);return RedirectToAction(nameof(Index));}}
